const { chromium } = require('playwright');
const base='http://127.0.0.1:8787';
const gif='data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==';
const assert=(value,message)=>{if(!value)throw new Error(message);};
async function api(request,method,path,data){const response=await request.fetch(`${base}${path}`,{method,headers:data===undefined?undefined:{'Content-Type':'application/json'},data});const payload=await response.json().catch(()=>({}));if(response.status()<200||response.status()>=300)throw new Error(`${method} ${path} failed (${response.status()}): ${payload.message||JSON.stringify(payload)}`);return payload;}
function lists(payload){return{relationships:payload.relationshipOptions||payload.relationships||payload.options?.relationships||[],intentions:payload.intentionOptions||payload.intentions||payload.options?.intentions||[]};}
async function create(browser,suffix,selection=null,owner=false){const context=await browser.newContext();const password=`Chat-${suffix}-Pass-2026!`;const username=`chat_${suffix}`;const signup=await context.request.post(`${base}/api/auth/signup`,{data:{username,displayName:`Chat ${suffix}`,email:`${username}@example.test`,password,rememberMe:false}});assert(signup.status()===201,`Signup ${suffix} failed.`);const onboarding=await api(context.request,'GET','/api/onboarding');const options=lists(onboarding);const relationshipId=selection?.relationshipId||options.relationships[0].id;const intentionIds=selection?.intentionIds||options.intentions.slice(0,2).map(item=>item.id);await api(context.request,'POST','/api/onboarding/relationship',{relationshipId});await api(context.request,'POST','/api/onboarding/intentions',{intentionIds});if(owner)await api(context.request,'POST','/api/bootstrap/owner',{password});const session=await api(context.request,'GET','/api/auth/session');return{context,id:session.user.id,username,selection:{relationshipId,intentionIds}};}
(async()=>{const browser=await chromium.launch({headless:true});let owner,visitor;try{owner=await create(browser,'owner',null,true);visitor=await create(browser,'visitor',owner.selection,false);console.log('CHAT CHECKPOINT: users ready');const ownerRooms=await api(owner.context.request,'GET','/api/chat/rooms');const visitorRooms=await api(visitor.context.request,'GET','/api/chat/rooms');const global=ownerRooms.rooms.find(room=>room.id==='chat-global');const group=ownerRooms.rooms.find(room=>room.type==='group'&&visitorRooms.rooms.some(other=>other.id===room.id));assert(global,'Global chat missing.');assert(group,'Shared group chat missing.');await api(owner.context.request,'POST','/api/chat/rooms/chat-global/messages',{type:'text',body:'Focused global message'});await api(owner.context.request,'POST',`/api/chat/rooms/${group.id}/messages`,{type:'text',body:'Focused group message'});const direct=await api(owner.context.request,'POST','/api/chat/direct',{userId:visitor.id});await api(owner.context.request,'POST',`/api/chat/rooms/${direct.roomId}/messages`,{type:'text',body:'Focused direct message'});await api(owner.context.request,'POST',`/api/chat/rooms/${direct.roomId}/messages`,{type:'gif',body:'Focused GIF',mediaUrl:gif});console.log('CHAT CHECKPOINT: all message types sent');const globalMessages=await api(visitor.context.request,'GET','/api/chat/rooms/chat-global/messages?after=0');const groupMessages=await api(visitor.context.request,'GET',`/api/chat/rooms/${group.id}/messages?after=0`);const directMessages=await api(visitor.context.request,'GET',`/api/chat/rooms/${direct.roomId}/messages?after=0`);assert(globalMessages.messages.some(message=>message.body==='Focused global message'),'Global message missing.');assert(groupMessages.messages.some(message=>message.body==='Focused group message'),'Group message missing.');assert(directMessages.messages.some(message=>message.type==='gif'&&message.mediaUrl===gif),'GIF message missing.');assert(directMessages.room.participant?.id===owner.id,'Direct participant card missing.');const progress=await api(owner.context.request,'GET',`/api/progression/${owner.id}`);assert(progress.profile.totalXp>=70,`Expected site/chat XP, got ${progress.profile.totalXp}.`);assert(progress.earned.length>=1,'No achievements unlocked.');assert(progress.achievements.every(item=>item.image_url),'Achievement image missing.');console.log(`CHAT CHECKPOINT: level ${progress.profile.level}, ${progress.profile.totalXp} XP, ${progress.earned.length} earned`);const page=await owner.context.newPage();const errors=[];page.on('pageerror',error=>errors.push(error.message));await page.goto(`${base}/dashboard`,{waitUntil:'networkidle'});await page.locator('#grev-chat-launcher').click();await page.locator('#grev-chat-panel').waitFor({state:'visible'});await page.locator('.grev-chat-room[data-room-id="chat-global"]').click();await page.getByText('Focused global message',{exact:true}).waitFor({state:'visible'});await page.locator('[data-chat-minimise]').click();await page.locator('#grev-chat-dock').waitFor({state:'visible'});await page.locator('#grev-chat-dock').click();await page.locator('#grev-chat-panel').waitFor({state:'visible'});assert(errors.length===0,`Chat UI errors: ${errors.join(' | ')}`);console.log('Chat and progression verification passed.');}finally{await owner?.context.close();await visitor?.context.close();await browser.close();}})().catch(error=>{console.error(`CHAT FAILURE: ${error.stack||error.message||error}`);process.exit(1);});
